 7	/**
 8	 * Default renderer for simulation cell colors.
 9	 */
10	public class DefaultCellColorStrategy implements CellColorStrategy
11	{
12	    private static final Color EMPTY_COLOR = Color.white;
13	    private static final Color UNKNOWN_COLOR = Color.gray;
14	    private static final Color INFECTED_COLOR = Color.green;
15	    private static final Color STORM_COLOR = Color.blue;
16	
17	    private final Map<Class<?>, Color> colors;
18	
19	    public DefaultCellColorStrategy()
20	    {
21	        colors = new HashMap<>();
22	        registerDefaultColors();
23	    }
24	
25	    @Override
26	    public void setColor(Class<?> animalClass, Color color)
27	    {
28	        colors.put(animalClass, color);
29	    }
30	
31	    @Override
32	    public void render(SimulationContext context, GridCanvas canvas)
33	    {
34	        Field field = context.getField();
35	        canvas.preparePaint();
36	
37	        Set<Location> stormLocations = stormLocations(context);
38	        for(int row = 0; row < field.getDepth(); row++) {
39	            for(int col = 0; col < field.getWidth(); col++) {
40	                Location location = new Location(row, col);
41	                Object creature = field.getObjectAt(row, col);
42	                Color color = EMPTY_COLOR;
43	
44	                if(creature != null) {
45	                    color = colorFor(creature);
46	                }
47	
48	                if(stormLocations.contains(location)) {
49	                    color = STORM_COLOR;
50	                }
51	
52	                canvas.drawMark(col, row, color);
53	            }
54	        }
55	
56	        canvas.repaint();
57	    }
58	
59	    private void registerDefaultColors()
60	    {
61	        setColor(Cod.class, Color.ORANGE);
62	        setColor(Salmon.class, Color.YELLOW);
63	        setColor(Seaweed.class, Color.RED);
64	        setColor(Shark.class, Color.BLACK);
65	        setColor(Whale.class, Color.PINK);
66	        setColor(Weather.class, STORM_COLOR);
67	    }
68	
69	    private Color colorFor(Object creature)
70	    {
71	        if(creature instanceof Animal) {
72	            Animal animal = (Animal)creature;
73	            if(animal.getIsInfected() && !animal.getIsImmuned()) {
74	                return INFECTED_COLOR;
75	            }
76	        }
77	
78	        Color color = colors.get(creature.getClass());
79	        if(color == null) {
80	            return UNKNOWN_COLOR;
81	        }
82	        return color;
83	    }
84	
85	    private Set<Location> stormLocations(SimulationContext context)
86	    {
87	        Set<Location> locations = new HashSet<>();
88	        Weather weather = context.getWeather();
89	        if(weather.getStormStart() && weather.getRandomLocation() != null) {
90	            locations.addAll(context.getField().adjacentLocationsIncludingSelf(weather.getRandomLocation(), weather.getStormScope()));
91	        }
92	        return locations;
93	    }
94	}

